import{_ as o}from"./chunks/library-overview.Bu864uIA.js";import{_ as r,o as e,c as a,a2 as d}from"./chunks/framework.Dx-TCpNt.js";const b=JSON.parse('{"title":"预处理与重命名","description":"KomaYomi 直接在你现有的图片文件夹里读取，不会复制或转换任何文件；只有你在预处理对话框里主动操作时，才会真实改名或拆分图片。也就是说，把一卷漫画加进图库前花的那几分钟整理，直接决定切格、配对和对照阅读顺不顺。有点麻烦，但总比同一页在三种语言里各返工一遍划算。","frontmatter":{"description":"KomaYomi 直接在你现有的图片文件夹里读取，不会复制或转换任何文件；只有你在预处理对话框里主动操作时，才会真实改名或拆分图片。也就是说，把一卷漫画加进图库前花的那几分钟整理，直接决定切格、配对和对照阅读顺不顺。有点麻烦，但总比同一页在三种语言里各返工一遍划算。"},"headers":[],"relativePath":"zh/guide/preprocess.md","filePath":"zh/guide/preprocess.md","lastUpdated":1794782163000}'),i={name:"zh/guide/preprocess.md"};function s(l,t,n,c,g,h){return e(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="预处理与重命名" tabindex="-1">预处理与重命名 <a class="header-anchor" href="#预处理与重命名" aria-label="Permalink to &quot;预处理与重命名&quot;">​</a></h1><p>KomaYomi 直接在你现有的图片文件夹里读取，不会复制或转换任何文件；只有你在预处理对话框里主动操作时，才会真实改名或拆分图片。也就是说，把一卷漫画加进图库前花的那几分钟整理，直接决定切格、配对和对照阅读顺不顺。有点麻烦，但总比同一页在三种语言里各返工一遍划算。</p><h2 id="这一步解决什么问题" tabindex="-1">这一步解决什么问题 <a class="header-anchor" href="#这一步解决什么问题" aria-label="Permalink to &quot;这一步解决什么问题&quot;">​</a></h2><p>自动切格偏爱干净的书页扫描。页面转倒了、扫描仪黑边还在、混着一堆 WebP、某个版本少了一页——图库照样能打开，但后面的每一步（配对、对齐、笔记、导出）都会继承这些毛病。在源头修一次就好。</p><h2 id="komayomi-会怎样处理你的文件" tabindex="-1">KomaYomi 会怎样处理你的文件 <a class="header-anchor" href="#komayomi-会怎样处理你的文件" aria-label="Permalink to &quot;KomaYomi 会怎样处理你的文件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>行为</th><th>后果</th></tr></thead><tbody><tr><td>图片从你指定的文件夹就地读取。</td><td>不会导入或复制，所有编辑都只写进 <code>data/</code>；只有使用预处理对话框时才会改名或拆分。</td></tr><tr><td>页面按<strong>排序位置</strong>配对，而不是按文件名。</td><td>改名会改变顺序。中间插入一页，后面的每一页都会顺延。</td></tr><tr><td>排序是自然排序：连续数字按数值比较。</td><td>即使不补零，<code>2.jpg</code> 也会排在 <code>10.jpg</code> 前面。</td></tr><tr><td>WebP 能显示，但不会解码用于切格检测。</td><td>依赖<strong>自动切格</strong>时，请把 WebP 转成 JPEG 或 PNG；预处理里的拆分也只支持 PNG/JPEG。</td></tr><tr><td>一个图片文件就是一页。</td><td>跨页扫描要么保持为一个文件，要么用预处理对每种语言同时拆分。</td></tr></tbody></table><figure class="shot"><img src="'+o+'" alt="整理好之后，图库侧栏中的卷、话与语言标记"><figcaption>整理好的一卷：每种语言一个文件夹，每一话一个文件夹，页数互相对齐，语言标记才会一致。</figcaption></figure><h2 id="整理清单" tabindex="-1">整理清单 <a class="header-anchor" href="#整理清单" aria-label="Permalink to &quot;整理清单&quot;">​</a></h2><p>如果原图很珍贵，先复制一份再动手。下面的顺序比用什么工具更重要。</p><ol><li><strong>转正、校正倾斜。</strong> 阅读方向是按页保存的，但一张横躺的扫描图，对照阅读救不回来。</li><li><strong>裁掉扫描仪黑边和对页阴影。</strong> 页边方正时，贴着边缘的分格更容易被正确检测。</li><li><strong>需要自动切格就把 WebP 转成 JPEG 或 PNG。</strong> 画质要足够高，保证台词仍然清楚。</li><li><strong>一话一个文件夹。</strong> 不要把两话混在同一目录里；话是分格模板、对齐预设和导出的基本单位。</li><li><strong>去掉不是正文页的图</strong>，例如封面、版权页、彩插，或另一版根本没有的赠品图。多出一页，后面每一页都会跟着错位。</li><li><strong>跨页要么不拆，要么每版都在同一位置拆。</strong> 一张跨页算一页。如果只拆了日文生肉、没拆中文熟肉，日文的第 12 页就会对应中文的第 12–13 页，配对立刻乱掉。用预处理里的**拆分…**可以一次切成所有语言。</li><li><strong>只在确实有帮助时规范文件名。</strong> 补零（<code>001.jpg</code>）便于对比和人工检查，但扫描器用的是排序位置和自然排序，<code>1.jpg</code> 与 <code>001.jpg</code> 都能用。预处理里的<strong>批量改名</strong>会整话重新编号，并同步迁移已保存的页面数据。</li></ol><h2 id="在-komayomi-里改名与拆分" tabindex="-1">在 KomaYomi 里改名与拆分 <a class="header-anchor" href="#在-komayomi-里改名与拆分" aria-label="Permalink to &quot;在 KomaYomi 里改名与拆分&quot;">​</a></h2><p>打开<strong>预处理…<strong>并选择卷。除了卷/话标题、页序、排除和页面角色，每个话的区块里还有一块</strong>磁盘文件</strong>，提供两个真实文件操作。图片格式转换仍然不在应用内。</p><p><strong>批量改名。</strong> 填好文件名前缀、起始编号和位数，点<strong>批量改名</strong>。应用会按按钮上方的页序（也就是你用箭头调好的顺序）重新编号，并真实改名磁盘文件（<code>001.jpg</code>、<code>002.jpg</code>……保留原扩展名）。话里所有「每一页都有图」的语言会一起改名，所以第 <em>n</em> 页在各语言里仍是同一张画；缺页的语言不动，并在结果里列出。</p><p>页面数据、历史、排除项、页面角色和已保存页序都按页序号索引，因此会在同一次操作里搬移并改写指向。应用内改名不会让批注、笔记或分格编辑丢失。改名后会重新载入本卷，请先应用其他改动，未保存的草稿会丢弃。</p><p>动手之前会先写一份清单到 <code>data/file-ops/</code>，列出每个旧名和新名。中途任何一步失败，整批都会回滚，清单标记为 <code>rolled-back</code>，目录保持原样。目标文件名若已属于别的文件，会直接报错拒绝，不会覆盖。</p><p><strong>拆分页面。</strong> 在某一页下方点<strong>拆分…</strong>，选择<strong>左右</strong>（跨页）或<strong>上下</strong>，填写切分位置百分比并确认。图片会切成 <code>&lt;原名&gt;-a</code> 与 <code>&lt;原名&gt;-b</code>，后半部分成为下一页，后面的页依次顺延。这一页存在的所有语言都在同一位置切分，配对不会错位。拆分只支持真正的 PNG/JPEG；WebP、GIF、BMP 会被拒绝。原图会先复制到 <code>data/file-ops/</code> 再从目录移除。</p><p>原页的页面文档会按两半裁剪：落在某半上的分格与批注保留在该半并重算坐标，分格笔记跟随分格，页级笔记留在前半页；两半都沿用原页的阅读方向。拆分后请检查两页，尤其是切口穿过分格的情况。</p><div class="warning custom-block"><p class="custom-block-title">改名与拆分无法在对话框里撤销</p><p><strong>恢复上一次应用</strong>横幅只回滚 <code>library.json</code>。改名和拆分在界面里是单向操作；需要找回原名或原图时，请使用 <code>data/file-ops/</code> 下的清单与备份目录。应用外改名仍然不安全：页面数据按页序号索引，文件管理器或命令行的改名不会搬移批注。</p></div><h2 id="开始标注前的确认" tabindex="-1">开始标注前的确认 <a class="header-anchor" href="#开始标注前的确认" aria-label="Permalink to &quot;开始标注前的确认&quot;">​</a></h2><ol><li>加入这一卷，在侧栏里打开。</li><li>看卷和话那一行的警告。<em>各语言页数不一致</em> 和 <em>文件名与页序不符</em> 这两条，通常说明整理时出了问题。</li><li>如果目录形状特殊，先打开<strong>目录识别规则…</strong>，用预览确认后再保存；见<a href="/KomaYomi-docs/zh/guide/folder-rules">目录识别规则</a>。</li><li>打开第一页、中间一页和最后一页，确认同一个分格里确实是同一块画面；如果不是，说明页数或跨页处理有问题。</li><li>这时再运行<strong>自动切格</strong>，开始写笔记。</li></ol><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>某种语言多了一页。</strong> 多半是多了一张封面或版权页。删掉它，或者给其他语言补上对应的一页。</li><li><strong>跨页只在一个版本里拆开了。</strong> 要么整页保留，要么每个版本都在同一位置拆。</li><li><strong>WebP 页面自动切格结果很乱。</strong> 转成其他格式；检测不会解码 WebP。</li><li><strong>在应用外改名后笔记跑到了下一页。</strong> 页面数据按序号索引，文件管理器/命令行的改名不会搬移它。请用预处理里的<strong>批量改名</strong>，或在标注前改名。</li><li><strong>拆分切口穿过了分格。</strong> 把切分位置放在分格之间，或者拆分后分别修正两半的分格；页级笔记按设计留在前半页。</li><li><strong>页面看起来没问题，缩略图却格式不一。</strong> 缩略图跟随文件内容而不是扩展名，一个其实是 JPEG 的 <code>.png</code> 仍能正常显示，这只是外观问题。</li><li><strong>标注之后才重组了文件夹。</strong> 识别出的 ID 变了，旧的页面数据就找不到了。目录规则要在标注之前应用。</li></ul><h2 id="缺失的截图" tabindex="-1">缺失的截图 <a class="header-anchor" href="#缺失的截图" aria-label="Permalink to &quot;缺失的截图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>图</th><th>用于</th></tr></thead><tbody><tr><td>改名前后对照</td><td>补零、自然排序与「磁盘文件」区块</td></tr><tr><td>拆分表单</td><td>跨页的方向与切分位置</td></tr><tr><td>跨页处理</td><td>整页保留与拆成两页的对比</td></tr><tr><td>图库警告条</td><td>用于确认的三类警告</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/zh/guide/gallery">图库与导入</a> —— 目录结构、语言别名与卷设置。</li><li><a href="/KomaYomi-docs/zh/guide/folder-rules">目录识别规则</a> —— 支持特殊目录结构。</li><li><a href="/KomaYomi-docs/zh/guide/panels">切格工作台</a> —— 第一页打开之后做什么。</li></ul>',26)])])}const u=r(i,[["render",s]]);export{b as __pageData,u as default};
